def countPalindromicSubsequences(s):
    MOD = 10 ** 9 + 7
    n = len(s)
    prv = [-1] * n      # previous index with the same letter
    nxt = [n] * n       # next index with the same letter
    last = {}
    for i in range(n):
        prv[i] = last.get(s[i], -1)
        last[s[i]] = i
    last = {}
    for i in range(n - 1, -1, -1):
        nxt[i] = last.get(s[i], n)
        last[s[i]] = i
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            inner = dp[i + 1][j - 1]
            if s[i] != s[j]:
                v = dp[i + 1][j] + dp[i][j - 1] - inner
            else:
                l, r = nxt[i], prv[j]
                if l > r:
                    v = 2 * inner + 2
                elif l == r:
                    v = 2 * inner + 1
                else:
                    v = 2 * inner - dp[l + 1][r - 1]
            dp[i][j] = v % MOD
    return dp[0][n - 1]
